			let firstEntered;
			const firstEnteredPromise = new Promise((resolve) => { firstEntered = resolve; });
			const holdFirst = new Promise((resolve) => { releaseFirst = resolve; });
			const holdTopic = async (data) => {
				if (data.title === title) {
					firstEntered();
					await holdFirst;
				}
				return data;
			};
			plugins.hooks.register('concurrent-topic-test', { hook: 'filter:topic.post', method: holdTopic });

			const [topicCountBefore, categoryCountBefore, userTopicCountBefore] = await Promise.all([
				db.getObjectField('global', 'topicCount'),
				db.getObjectField(`category:${categoryObj.cid}`, 'topic_count'),
				db.sortedSetCard(`uid:${adminUid}:topics`),
			]);
			const postTopic = () => helpers.request('post', '/api/v3/topics', {
				form: { cid: categoryObj.cid, title, content: 'A concurrent topic' },
				jar: adminJar,
				json: true,
			});
			try {
				const first = postTopic();
				await firstEnteredPromise;
				const rejected = await Promise.all(Array.from({ length: 4 }, () => postTopic()));
				rejected.forEach(({ res, body }) => {
					assert.strictEqual(res.statusCode, 400);
					assert.strictEqual(body.status.code, 'bad-request');
				});
				releaseFirst();
				const { res, body } = await first;
				assert.strictEqual(res.statusCode, 200);
				assert.strictEqual(body.status.code, 'ok');
