const Topics = module.exports;

Topics.lockPosting = async (req, error) => {
	const key = `posting${req.uid || req.sessionID}`;
	const token = crypto.randomBytes(16).toString('hex');
	if (!await db.acquirePostingLock(key, token)) {
		throw new Error(error);
	}
	return `${key}:${token}`;
};

async function releasePosting(lock) {
	const separator = lock.lastIndexOf(':');
	await db.releasePostingLock(lock.slice(0, separator), lock.slice(separator + 1));
}

Topics.get = async (req, res) => {
	helpers.formatApiResponse(200, res, await api.topics.get(req, req.params));
};

Topics.create = async (req, res) => {
	const lock = await Topics.lockPosting(req, '[[error:too-many-posts, 1]]');
	try {
		const payload = await api.topics.create(req, req.body);
		if (payload.queued) {
			helpers.formatApiResponse(202, res, payload);
		} else {
			helpers.formatApiResponse(200, res, payload);
		}
	} finally {
		await releasePosting(lock);
	}
};

